const items = $input.all();
const normalized = [];

for (const item of items) {
  const xml = item.json.body || item.json;
  const titleMatch = xml.match(/<title><!\[CDATA\[([^\]]+)\]\]><\/title>|<title>([^<]+)<\/title>/);
  const linkMatch = xml.match(/<link>([^<]+)<\/link>/);
  const descMatch = xml.match(/<description><!\[CDATA\[([^\]]+)\]\]><\/description>|<description>([^<]+)<\/description>/);
  const pubDateMatch = xml.match(/<pubDate>([^<]+)<\/pubDate>/);
  const categoryMatch = xml.match(/<category>([^<]+)<\/category>/);

  normalized.push({
    json: {
      title: titleMatch ? (titleMatch[1] || titleMatch[2]) : 'Untitled',
      url: linkMatch ? linkMatch[1] : '',
      source: 'bbc_news',
      summary: descMatch ? (descMatch[1] || descMatch[2]) : null,
      published_at: pubDateMatch ? new Date(pubDateMatch[1]).toISOString() : new Date().toISOString(),
      category: categoryMatch ? categoryMatch[1] : 'others'
    }
  });
}

return normalized;

